const rawRunId = process.env.ZEALT_RUN_ID;

if (!rawRunId) {
  throw new Error("ZEALT_RUN_ID is required");
}

const safeRunId = rawRunId.replace(/-/g, "_");

export const usersTableName = `users_${safeRunId}` as const;
export const documentsTableName = `documents_${safeRunId}` as const;

import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

import { documentsTableName, usersTableName } from "./tableNames";

export default defineSchema({
  [usersTableName]: defineTable({
    name: v.string(),
    role: v.string(),
  }),
  [documentsTableName]: defineTable({
    title: v.string(),
    content: v.string(),
    authorId: v.id(usersTableName),
  }),
});

import { ConvexError, v } from "convex/values";
import { mutation, query } from "./_generated/server";
import { documentsTableName, usersTableName } from "./tableNames";
import { Id } from "./_generated/dataModel";

const getUserById = async (ctx: { db: any }, userId: string) => {
  const user = await ctx.db.get(userId as Id<typeof usersTableName>);
  if (!user) {
    throw new ConvexError("Unauthorized");
  }
  return user;
};

export const get = query({
  args: { userId: v.string() },
  handler: async (ctx) => {
    return await ctx.db.query(documentsTableName).collect();
  },
});

export const create = mutation({
  args: {
    userId: v.string(),
    title: v.string(),
    content: v.string(),
  },
  handler: async (ctx, args) => {
    const user = await getUserById(ctx, args.userId);
    if (user.role !== "admin" && user.role !== "editor") {
      throw new ConvexError("Unauthorized");
    }

    const documentId = await ctx.db.insert(documentsTableName, {
      title: args.title,
      content: args.content,
      authorId: args.userId as Id<typeof usersTableName>,
    });

    return documentId;
  },
});

export const deleteDocument = mutation({
  args: {
    userId: v.string(),
    documentId: v.string(),
  },
  handler: async (ctx, args) => {
    const user = await getUserById(ctx, args.userId);
    if (user.role !== "admin") {
      throw new ConvexError("Unauthorized");
    }

    await ctx.db.delete(args.documentId as Id<typeof documentsTableName>);
  },
});

import { mutation } from "./_generated/server";

import { usersTableName } from "./tableNames";

export const seed = mutation({
  args: {},
  handler: async (ctx) => {
    const adminId = await ctx.db.insert(usersTableName, {
      name: "Admin",
      role: "admin",
    });
    const editorId = await ctx.db.insert(usersTableName, {
      name: "Editor",
      role: "editor",
    });
    const viewerId = await ctx.db.insert(usersTableName, {
      name: "Viewer",
      role: "viewer",
    });

    return { adminId, editorId, viewerId };
  },
});

